package com.hector.workouttracker.core.catalog

import com.hector.workouttracker.core.model.trackerJson
import com.hector.workouttracker.core.model.visibleName
import kotlinx.serialization.json.*

data class StarterRoutine(val id: String, val name: String, val exercises: List<String>)

/** Generated by the PWA builder; reference IDs are validated, then only names enter storage. */
class StarterLibrary private constructor(val routines: List<StarterRoutine>) {
    companion object {
        fun parse(text: String, catalog: ExerciseCatalog): StarterLibrary {
            val root = trackerJson.parseToJsonElement(text).jsonObject
            require(root.getValue("formatVersion").jsonPrimitive.int == 1)
            require(root.getValue("sourceRevision").jsonPrimitive.content == catalog.sourceRevision)
            val reference = catalog.exercises.groupBy { it.id }
            val routines =
                root.getValue("routines").jsonArray.map { row ->
                    val value = row.jsonObject
                    val name = value.getValue("name").jsonPrimitive.content
                    val id = value.getValue("id").jsonPrimitive.content
                    require(visibleName(name, 80) && id == "starter:v1:$name")
                    val ids = mutableSetOf<String>()
                    val exercises =
                        value.getValue("exercises").jsonArray.map { entry ->
                            val exercise = entry.jsonObject
                            val catalogId = exercise.getValue("catalogId").jsonPrimitive.content
                            val savedName = exercise.getValue("name").jsonPrimitive.content
                            val record = requireNotNull(reference[catalogId]?.singleOrNull())
                            require(
                                ids.add(catalogId) &&
                                    record.name == savedName &&
                                    record.instructions.isNotEmpty()
                            )
                            savedName
                        }
                    require(if (name == "Custom") exercises.isEmpty() else exercises.size == 4)
                    StarterRoutine(id, name, exercises)
                }
            require(routines.size == 6 && routines.last().name == "Custom")
            require(routines.map { catalogKey(it.name) }.distinct().size == routines.size)
            return StarterLibrary(routines)
        }
    }
}
